set -euo pipefail
cd /home/ubuntu/apps/travel-planner
mkdir -p /tmp/travel-route-stage/service /tmp/travel-route-stage/eval rag/eval/baselines/routing_rule_v1/service
touch /tmp/travel-route-stage/service/__init__.py
cp rag/service/ticket_service.py rag/eval/baselines/routing_rule_v1/service/ticket_service.py
cp rag/service/retrieval_server.py rag/eval/baselines/routing_rule_v1/service/retrieval_server.py
echo  | base64 -d > /tmp/travel-route-stage/service/answer_service.py
echo  | base64 -d > /tmp/travel-route-stage/service/retrieval_server.py
echo  | base64 -d > /tmp/travel-route-stage/service/ticket_service.py
echo  | base64 -d > /tmp/travel-route-stage/service/intent_classifier.py
echo  | base64 -d > /tmp/travel-route-stage/eval/test_answer_service.py
echo  | base64 -d > /tmp/travel-route-stage/eval/test_ticket_service.py
echo  | base64 -d > /tmp/travel-route-stage/eval/test_intent_classifier.py
echo  | base64 -d > docs/ROUTING_STORE_CONTRACT.md
echo  | base64 -d > rag/eval/run_routing_eval.py
echo  | base64 -d > rag/eval/cases/routing_store_v1.jsonl
echo  | base64 -d > rag/eval/cases/routing_store_v1.manifest.json
export PYTHONPATH=/tmp/travel-route-stage:rag
.venv/bin/python -m unittest discover -s /tmp/travel-route-stage/eval -p 'test_*.py' -v
.venv/bin/python rag/eval/run_routing_eval.py --output rag/eval/reports/routing_legacy_rule_v1.json
free -m
ps -o rss= -p "$(cat /tmp/rag_retrieval_server.pid)"
